from selenium.webdriver.common.by import By
from taf.selenium.mobile.gnb.oam.coam.classical.exceptions import ParamValueError


class Menu(object):
    APP_MAIN_MENU_XPATH = '//div[@class="app-name-mob"]/i'
    APP_SUB_MENU_XPATH = '//div[contains(text(), "{sub_menu}")]'
    APP_CURRENT_PAGE_XPATH = '//div[@class="app-name-mob"]/span[contains(text(), "{}")]'

    def __init__(self, tool, route_list):
        self._tool = tool
        self._menu_list = route_list

    def navigate(self):
        self._open_page()

    def _open_page(self):
        """
        Open a new page of selenium_coam web, if target page has been opened, it won't be opened again
        :param menu_list: the menu list of selenium_coam's page
        """
        if not self._menu_list:
            raise ParamValueError("menu list is empty")

        if self._is_page_active():
            return

        menu_xpath_list = list()
        menu_xpath_list.append(self.APP_MAIN_MENU_XPATH)
        for menu in self._menu_list:
            menu_xpath_list.append(self.APP_SUB_MENU_XPATH.format(sub_menu=menu))

        for xpath in menu_xpath_list:
            self._tool.wait_for_visibility((By.XPATH, xpath))
            self._tool.click_enabled_element((By.XPATH, xpath))

    def _is_page_active(self):
        return self._tool.element_exists((By.XPATH, self.APP_CURRENT_PAGE_XPATH.format(self._menu_list[-1])))
